    x,
    y: 0,
    vx: 0,
    vy: 0,
    facing,
    health: rules.maxHealth,
    stamina: rules.maxStamina,
    staminaIdle: 0,
    action: "idle",
    actionFrame: 0,
    timer: 0,
    moveId: null,
    moveHit: false,
    crouching: false,
    combo: 0,
    held: 0,
    buffer: EMPTY_BUFFER,
    kit,
    bolt: null,
    zone: null,
    obscured: false,
  });
