  return this.finalIsland;
}

/** The derived seeds of the systems seeded so far, for tests: each differs, and none reads the match code. */
derivedSeeds(): Record<"world" | "ledger" | "final-socket" | "intel" | "ruins", number> {
  return { world: this.seedOf("world"), ledger: this.seedOf("ledger"), "final-socket": this.seedOf("final-socket"), intel: this.seedOf("intel"), ruins: this.seedOf("ruins") };
