import * as Phaser from "phaser";
import { defaultDuelConfig, findMove, worldBox, type DuelState, type FighterState, type WorldBox } from "@pirate-sea-race/simulation/duel";
import type { DuelFeedEvent } from "@pirate-sea-race/simulation/netcode";
import { ArenaFlashes, type ArenaFlash } from "./duelEvents.js";
import { cssColor } from "./matchView.js";

const { moveset } = defaultDuelConfig;
const SUB = moveset.arena.subPixelsPerPixel;
export const ARENA_WIDTH = moveset.arena.width / SUB;
export const ARENA_HEIGHT = 320;
/** The floor's height on the canvas, in pixels from the top. */
const FLOOR = ARENA_HEIGHT - 40;

export const FIGHTER_COLORS = [0xf4b942, 0x3dd6d0] as const;
const BACKGROUND = 0x1b2a38;
const FLOOR_COLOR = 0x3b5266;
const HURTBOX_COLOR = 0x46e06b;
const HITBOX_COLOR = 0xff3b30;
const PUSHBOX_COLOR = 0x6aa9ff;

/** What the arena draws from: the client's predicted duel, its fresh events, and the view options. */
export interface ArenaSource {
  /** The predicted state to draw, or undefined before the duel exists. */
  state(): DuelState | undefined;
  /** Events of newly simulated frames, each once (stable ids). */
  drainEvents(): DuelFeedEvent[];
  /** The predicted state of an earlier frame, while the client still holds it. */
  stateAt(frame: number): DuelState | undefined;
  /** The developer toggle: draw hurtboxes, pushboxes and active hitboxes. */
  showBoxes(): boolean;
  /** Big centred text: the countdown, or the result. */
  banner(): string;
  /** Called once the arena is up (at sea the fight waits for both fighters' arenas, §6). */
  ready?(): void;
}

/** A fighter as drawn this frame, for the DOM report the browser tests read. */
export interface DrawnFighter {
  readonly x: number;
  readonly y: number;
  readonly action: string;
  readonly moveId: string | null;
  readonly facing: number;
  readonly health: number;
}

/** Arena pixels of a box in sub-pixels (y up from the floor). */
function toCanvas(box: WorldBox): { x: number; y: number; w: number; h: number } {
  return { x: box.x0 / SUB, y: FLOOR - box.y1 / SUB, w: (box.x1 - box.x0) / SUB, h: (box.y1 - box.y0) / SUB };
}

function stance(fighter: FighterState): "standing" | "crouching" | "airborne" {
  if (fighter.y > 0 || fighter.vy > 0 || fighter.action === "jump") return "airborne";
  return fighter.crouching ? "crouching" : "standing";
}

/** The fighter's active hitbox this frame, if its move is on an active frame. */
function activeHitbox(fighter: FighterState): WorldBox | undefined {
  if (fighter.action !== "attack" || fighter.moveId === null) return undefined;
  const move = findMove(moveset, fighter.moveId);
  const frame = fighter.actionFrame;
  const active = typeof move.timing.active === "number" ? move.timing.active : 0;
  if (frame <= move.timing.startup || frame > move.timing.startup + active) return undefined;
  return worldBox(move.hitbox, fighter.x, fighter.y, fighter.facing);
}

/** The outline colour that tells the fighter's state at a glance. */
function stateColor(fighter: FighterState): number {
  switch (fighter.action) {
    case "hitstun":
    case "knockdown":
      return 0xff5a4f;
    case "blockstun":
      return 0xffffff;
    case "stagger":
      return 0xff9f1c;
    case "thrown":
    case "throw-break":
      return 0xc77dff;
    case "attack":
      return activeHitbox(fighter) === undefined ? 0xfff3b0 : 0xff3b30;
    default:
      return 0x0b1620;
  }
}

function actionLabel(fighter: FighterState): string {
  if (fighter.action === "attack" && fighter.moveId !== null) {
    const move = findMove(moveset, fighter.moveId);
    return `${move.timing.name} ${fighter.actionFrame}`;
  }
  return fighter.crouching && fighter.action !== "crouch" ? `${fighter.action} (low)` : fighter.action;
}

/**
 * The duel arena with placeholder shapes: each fighter is its stance's hurtbox in its colour, outlined by its state
 * (red when hit, white when blocking, yellow in startup, red while its hitbox is active), with a nose on the side it
 * faces and its current move above it. The developer toggle adds every hurtbox, pushbox and active hitbox. Hits,
 * blocks, throws and the KO flash once each, by their stable event ids (`ArenaFlashes`). The scene reports what it
 * drew as data attributes on its report element (`data-fighters`, `data-boxes`, `data-frame`) for the browser tests.
 *
 * It is one scene of the page's one game: the whole game of a standalone duel (`startArena`), or in a match the scene
 * the sea gives way to for a duel at sea, started with that duel's source (`scene.start("arena", { source })`). On a
 * canvas larger than the arena, the camera scales it to fit and centres it.
 */
export class ArenaScene extends Phaser.Scene {
  private graphics!: Phaser.GameObjects.Graphics;
  private boxes!: Phaser.GameObjects.Graphics;
  private labels: Phaser.GameObjects.Text[] = [];
  private bannerText!: Phaser.GameObjects.Text;
  private flashes = new ArenaFlashes();
  private readonly flashTexts = new Map<string, Phaser.GameObjects.Text>();
  private lastReport = "";
  /** Frames whose active hitbox was drawn, since the page loaded. */
  private hitboxFrames = 0;
  /** The frame drawn last: hitboxes of the frames stepped since then are drawn too, so a slow render misses none. */
  private lastDrawnFrame = -1;

  constructor(
    private readonly report: HTMLElement,
    private source?: ArenaSource,
  ) {
    super("arena");
  }

  /** A start with a new source (the next duel at sea) begins a fresh picture. */
  init(data?: { source?: ArenaSource }): void {
    if (data?.source === undefined || data.source === this.source) return;
    this.source = data.source;
    this.flashes = new ArenaFlashes();
    this.flashTexts.clear();
    this.lastReport = "";
    this.lastDrawnFrame = -1;
  }

  create(): void {
    const camera = this.cameras.main;
    camera.setBackgroundColor(BACKGROUND);
    const zoom = Math.min(this.scale.width / ARENA_WIDTH, this.scale.height / ARENA_HEIGHT);
    if (zoom !== 1) camera.setZoom(zoom).centerOn(ARENA_WIDTH / 2, ARENA_HEIGHT / 2);
    const floor = this.add.graphics();
    floor.fillStyle(FLOOR_COLOR, 1);
    floor.fillRect(0, FLOOR, ARENA_WIDTH, ARENA_HEIGHT - FLOOR);
    this.graphics = this.add.graphics().setDepth(1);
    this.boxes = this.add.graphics().setDepth(2);
    const style = { fontFamily: "system-ui, sans-serif", fontSize: "12px", color: "#e8f1f5" };
    this.labels = [this.add.text(0, 0, "", style).setOrigin(0.5, 1).setDepth(3), this.add.text(0, 0, "", style).setOrigin(0.5, 1).setDepth(3)];
    this.bannerText = this.add
      .text(ARENA_WIDTH / 2, 90, "", { fontFamily: "system-ui, sans-serif", fontSize: "36px", color: "#fff3b0" })
      .setOrigin(0.5, 0.5)
      .setDepth(4);
    this.source?.ready?.();
  }

  override update(time: number): void {
    const source = this.source;
    if (source === undefined) return;
    const state = source.state();
    this.graphics.clear();
    this.boxes.clear();
    this.bannerText.setText(source.banner());
    if (state === undefined) return;
    const showBoxes = source.showBoxes();
    let hurtboxes = 0;
    let hitboxes = 0;
    state.fighters.forEach((fighter, index) => {
      const body = toCanvas(worldBox(moveset.fighter.hurtboxes[stance(fighter)], fighter.x, fighter.y, fighter.facing));
      const knockedDown = fighter.action === "knockdown";
      this.graphics.fillStyle(FIGHTER_COLORS[index]!, 1);
      if (knockedDown) this.graphics.fillRect(body.x - body.h / 4, FLOOR - body.w / 2, body.h / 2, body.w / 2);
      else this.graphics.fillRect(body.x, body.y, body.w, body.h);
      this.graphics.lineStyle(3, stateColor(fighter), 1);
      if (!knockedDown) this.graphics.strokeRect(body.x, body.y, body.w, body.h);
      // The nose: which way the fighter faces.
      const noseX = fighter.facing === 1 ? body.x + body.w : body.x;
      this.graphics.fillStyle(0x0b1620, 1);
      this.graphics.fillTriangle(noseX, body.y + 10, noseX + 8 * fighter.facing, body.y + 16, noseX, body.y + 22);
      this.labels[index]!.setPosition(body.x + body.w / 2, body.y - 4).setText(actionLabel(fighter));

      if (!showBoxes) return;
      hurtboxes++;
      this.boxes.lineStyle(2, HURTBOX_COLOR, 1);
      this.boxes.strokeRect(body.x - 3, body.y - 3, body.w + 6, body.h + 6);
      const { halfWidth, height } = moveset.fighter.pushbox;
      const push = toCanvas({ x0: fighter.x - halfWidth, x1: fighter.x + halfWidth, y0: fighter.y, y1: fighter.y + height });
      this.boxes.lineStyle(1, PUSHBOX_COLOR, 0.8);
      this.boxes.strokeRect(push.x, push.y, push.w, push.h);
    });
    if (showBoxes) {
      // Every active hitbox since the last picture: at 60 fps just this frame's, on a slower render the skipped ones too.
      const first = Math.min(state.frame, Math.max(this.lastDrawnFrame + 1, state.frame - 60));
      for (let frame = first; frame <= state.frame; frame++) {
        const past = frame === state.frame ? state : source.stateAt(frame);
        const active = past?.fighters.map(activeHitbox).filter((box) => box !== undefined) ?? [];
        if (active.length > 0 && frame > this.lastDrawnFrame) this.hitboxFrames++;
        for (const hit of active) {
          if (frame === state.frame) hitboxes++;
          const box = toCanvas(hit);
          this.boxes.fillStyle(HITBOX_COLOR, frame === state.frame ? 0.6 : 0.3);
          this.boxes.fillRect(box.x, box.y, box.w, box.h);
        }
      }
    }
    this.lastDrawnFrame = state.frame;

    for (const flash of this.flashes.add(source.drainEvents(), time)) this.flash(flash, state);
    for (const flash of this.flashes.expire(time)) {
      this.flashTexts.get(flash.id)?.destroy();
      this.flashTexts.delete(flash.id);
    }

    const drawn: DrawnFighter[] = state.fighters.map((fighter) => ({
      x: fighter.x,
      y: fighter.y,
      action: fighter.action,
      moveId: fighter.moveId,
      facing: fighter.facing,
      health: fighter.health,
    }));
    const report = JSON.stringify(drawn);
    if (report !== this.lastReport) {
      this.report.dataset["fighters"] = report;
      this.lastReport = report;
    }
    this.report.dataset["frame"] = String(state.frame);
    this.report.dataset["boxes"] = JSON.stringify({ shown: showBoxes, hurtboxes, hitboxes, hitboxFrames: this.hitboxFrames });
  }

  /** A short text over the fighter an event happened to (the flash's text and lifetime come from `flashFor`). */
  private flash(flash: ArenaFlash, state: DuelState): void {
    const x = flash.over === "centre" ? ARENA_WIDTH / 2 : state.fighters[flash.over].x / SUB;
    const y = flash.over === "centre" ? 140 : FLOOR - 120;
    const label = this.add.text(x, y, flash.text, { fontFamily: "system-ui, sans-serif", fontSize: "18px", color: cssColor(0xfff3b0) }).setOrigin(0.5, 0.5).setDepth(5);
    this.flashTexts.set(flash.id, label);
  }
}

/**
 * The arena is a few flat shapes, so it uses Phaser's canvas renderer: without a GPU (a software WebGL) WebGL would
 * cost the main thread tens of milliseconds a frame, which the client's 4 ms tick and the round-trip probes share.
 */
export function startArena(parent: HTMLElement, source: ArenaSource): Phaser.Game {
  return new Phaser.Game({
    type: Phaser.CANVAS,
    parent,
    width: ARENA_WIDTH,
    height: ARENA_HEIGHT,
    backgroundColor: BACKGROUND,
    banner: false,
    audio: { noAudio: true },
    scene: new ArenaScene(parent, source),
  });
}

export { HITBOX_COLOR, HURTBOX_COLOR };
import {
  duelFrameBundleSchema,
  DuelMessageType,
  duelProbeSchema,
  type DuelPracticeMessage,
  type DuelProbeReply,
  type DuelRoomPhase,
  type DummyBehaviour,
} from "@pirate-sea-race/protocol";
import { createDuelState, defaultDuelConfig, type DuelState, type PlayerIndex } from "@pirate-sea-race/simulation/duel";
import { DuelClientSession, type DuelFeedEvent } from "@pirate-sea-race/simulation/netcode";
import type { ArenaSource } from "./arenaScene.js";
import { PendingDuelEvents } from "./duelEvents.js";
import { renderDuelHud, resultText, type DuelConnectionStatus } from "./duelHud.js";
import { DuelKeyboard } from "./duelKeyboard.js";
import type { DuelLobby, DuelTransport } from "./duelTransport.js";

/** The client ticks this often: far finer than a frame, and independent of the display's refresh rate. */
const TICK_MS = 4;
/** The HUD is redrawn this often. */
const HUD_MS = 50;
/** Tick intervals kept for diagnostics: the last 2000 (about eight seconds of fight at 4 ms). */
const INTERVAL_SAMPLES = 2000;

const { rules } = defaultDuelConfig.moveset;

/**
 * One browser's duel, over a standalone duel room or inside a match room (the `DuelTransport` seam): the duel's
 * messages feed a `DuelClientSession` (the same rollback core the headless test client runs), a 4 ms timer ticks it
 * with the keyboard's input and sends what it returns, the arena draws the predicted state, and the HUD shows the
 * confirmed one. `window.__duel` exposes read-only diagnostics for tests. `dispose` stops it (a duel at sea ends).
 */
export class DuelClient implements ArenaSource {
  private session: DuelClientSession | undefined;
  private status: DuelConnectionStatus = "connected";
  private boxes = false;
  private readonly keyboard: DuelKeyboard;
  private readonly timers: number[] = [];
  private readonly unsubscribe: (() => void)[] = [];
  private readonly pendingEvents = new PendingDuelEvents();
  /** Milliseconds between consecutive ticks while the fight runs: how responsive the client's tick is on this machine. */
  private readonly intervals: number[] = [];
  private lastTickAt: number | undefined;

  constructor(
    private readonly transport: DuelTransport,
    private readonly hud: HTMLElement,
  ) {
    this.keyboard = new DuelKeyboard(window);
    this.unsubscribe.push(
      transport.onMessage(DuelMessageType.Probe, (message: unknown) => {
        const probe = duelProbeSchema.safeParse(message);
        if (!probe.success) return;
        transport.send(DuelMessageType.Probe, { id: probe.data.id } satisfies DuelProbeReply);
        this.ensureSession()?.receiveProbe(probe.data, performance.now());
      }),
      transport.onMessage(DuelMessageType.Frames, (message: unknown) => {
        const bundle = duelFrameBundleSchema.safeParse(message);
        if (bundle.success) this.ensureSession()?.receiveBundle(bundle.data, performance.now());
      }),
      transport.onDrop(() => {
        this.status = "reconnecting";
      }),
      transport.onReconnect(() => {
        this.status = "connected";
      }),
      transport.onLeave(() => {
        this.status = "disconnected";
        this.renderHud();
        this.stopTimers();
      }),
    );
    this.timers.push(window.setInterval(() => this.tick(), TICK_MS));
    this.timers.push(window.setInterval(() => this.renderHud(), HUD_MS));
    (window as unknown as { __duel: unknown }).__duel = {
      stats: () => this.session?.stats,
      frame: () => this.session?.frame,
      confirmedFrame: () => this.session?.rollback.confirmedFrame,
      lastTaggedFrame: () => this.session?.lastTaggedFrame,
      /** Milliseconds between consecutive client ticks during the fight (the last INTERVAL_SAMPLES). */
      tickIntervals: () => [...this.intervals],
      /** The input bits this client tagged for frames `from` to `to` (0 where none was). */
      taggedInputs: (from: number, to: number) =>
        Array.from({ length: Math.max(0, to - from + 1) }, (_, index) => this.session?.rollback.localInput(from + index) ?? 0),
    };
  }

  /** The developer toggle for hurtboxes and hitboxes. */
  setShowBoxes(show: boolean): void {
    this.boxes = show;
  }

  /** Practice rooms: the dummy idles or guards. */
  setDummy(dummy: DummyBehaviour): void {
    this.transport.send(DuelMessageType.Practice, { dummy } satisfies DuelPracticeMessage);
  }

  /** The arena is up: at sea the fight waits for both fighters to say so (§6). */
  ready(): void {
    this.transport.ready();
  }

  /** Stops the timers, the keyboard and the subscriptions: this duel is over and its view is gone. */
  dispose(): void {
    this.stopTimers();
    this.keyboard.dispose();
    for (const unsubscribe of this.unsubscribe.splice(0)) unsubscribe();
  }

  state(): DuelState | undefined {
    return this.session?.state;
  }

  drainEvents(): DuelFeedEvent[] {
    this.collectEvents();
    return this.pendingEvents.drain();
  }

  stateAt(frame: number): DuelState | undefined {
    return this.session?.rollback.stateAt(frame);
  }

  showBoxes(): boolean {
    return this.boxes;
  }

  banner(): string {
    const lobby = this.transport.lobby();
    if (lobby === undefined) return "";
    if (lobby.phase === "waiting") return lobby.practice ? "" : "Waiting for an opponent";
    if (lobby.phase === "countdown") return String(Math.max(1, Math.ceil(lobby.countdown / 60)));
    if (lobby.phase === "over") return resultText(lobby.winner, lobby.reason);
    return (this.session?.frame ?? 0) < 45 ? "FIGHT" : "";
  }

  private get self(): PlayerIndex | undefined {
    const seats = this.transport.lobby()?.seats;
    const seat = seats === undefined ? undefined : [...seats].find((entry) => entry.sessionId === this.transport.sessionId);
    return seat === undefined ? undefined : (seat.slot as PlayerIndex);
  }

  /**
   * The session, created once the lobby is known. At sea it is dropped while the duel waits for a fighter who is still
   * loading after the countdown, so the fight's clock starts from the fight's own frames, not from a paused countdown.
   */
  private ensureSession(): DuelClientSession | undefined {
    const lobby = this.transport.lobby();
    if (lobby?.phase === "waiting") this.session = undefined;
    if (this.session !== undefined) return this.session;
    const self = this.self;
    if (lobby === undefined || lobby.phase === "waiting" || self === undefined) return undefined;
    this.session = new DuelClientSession({ config: defaultDuelConfig, player: self, initial: createDuelState(defaultDuelConfig, { seed: lobby.seed }) });
    return this.session;
  }

  private tick(): void {
    const now = performance.now();
    if (this.transport.lobby()?.phase === "fighting") {
      if (this.lastTickAt !== undefined) {
        this.intervals.push(now - this.lastTickAt);
        if (this.intervals.length > INTERVAL_SAMPLES) this.intervals.shift();
      }
      this.lastTickAt = now;
    } else this.lastTickAt = undefined;
    const session = this.ensureSession();
    if (session === undefined) return;
    // Once the result is in, nothing the player presses matters any more, but the final bundle is still stepped, so
    // the HUD's health, clock and result end on the server's last frame.
    const lobby = this.transport.lobby();
    if (lobby?.phase === "over") {
      session.finish();
      this.collectEvents();
      return;
    }
    const delay = lobby?.inputDelay ?? 0;
    if (delay > 0) session.inputDelay = delay;
    const tagged = session.lastTaggedFrame;
    const message = session.tick(performance.now(), this.keyboard.bits());
    if (session.lastTaggedFrame > tagged) this.keyboard.framesTagged();
    if (message !== undefined) this.transport.send(DuelMessageType.Input, message);
    this.collectEvents();
  }

  /** Events are drained every tick, so none is lost while the arena is not drawing (a hidden tab). */
  private collectEvents(): void {
    this.pendingEvents.collect(this.session?.drainEvents() ?? []);
  }

  private stopTimers(): void {
    for (const timer of this.timers.splice(0)) window.clearInterval(timer);
  }

  private renderHud(): void {
    const lobby: DuelLobby | undefined = this.transport.lobby();
    const self = this.self;
    if (lobby === undefined || self === undefined) return;
    const session = this.session;
    const seats = [...lobby.seats];
    const connected = [0, 1].map((slot) => seats.find((seat) => seat.slot === slot)?.connected ?? false) as [boolean, boolean];
    renderDuelHud(this.hud, {
      code: lobby.code,
      practice: lobby.practice,
      phase: lobby.phase as DuelRoomPhase,
      status: this.status,
      self,
      countdown: lobby.countdown,
      connected,
      confirmed: session?.confirmedState ?? createDuelState(defaultDuelConfig, { seed: lobby.seed }),
      maxHealth: rules.maxHealth,
      maxStamina: rules.maxStamina,
      roundFrames: rules.roundFrames,
      overtimeFrames: rules.overtimeFrames,
      rttMs: session?.rttMs ?? 0,
      inputDelay: lobby.inputDelay,
      corrections: session?.stats.corrections ?? 0,
      result: lobby.phase === "over" ? { winner: lobby.winner, reason: lobby.reason } : undefined,
    });
  }
}

