1	import { rulesPresets, type RulesPresetId, type SeaMapDefinition } from "@pirate-sea-race/content";
2	import type { FruitInspectedMessage, TestFruits } from "@pirate-sea-race/protocol";
3	import { createFruitState, inspectPedestal, type FruitSite, type FruitState } from "@pirate-sea-race/simulation/fruits";
4	import { dockCentre, islandDocks, MATCH_PRESET } from "./objectives.js";
5	
6	/**
7	 * The room's side of §9's fruit pedestals (`docs/fruits.md`): where the pedestals stand on the sea, a match's deal and
8	 * what an inspection sends. The fruit rules alone decide who eats what; nothing here eats a fruit.
9	 */
10	
11	/** A pedestal on the sea: the fruit rules' site, plus the island and the dock a player moors at to reach it. */
...
35	  /** The fruit seed derived from the match's master secret (`deriveSeed('fruit')`), never the match code (§3, §16). */
36	  readonly seed: number;
37	  /** Test-only: the kit on each site, in site order, instead of the seeded deal. */
38	  readonly layout?: TestFruits | undefined;
39	}
40	
41	/**
42	 * A new match's fruit state: the fruit rules' seeded deal onto the sites. A test-only layout replaces the deal's kits,
43	 * and must hold the same fruit as the deal (two of each kit).
44	 */
45	export function createMatchFruits(options: MatchFruitsOptions): FruitState {
46	  const dealt = createFruitState(options.sites, options.seed >>> 0, rulesPresets[MATCH_PRESET]);
47	  const layout = options.layout;
48	  if (layout === undefined) return dealt;
49	  const deck = dealt.pedestals.map((pedestal) => pedestal.kit).sort();
50	  if ([...layout].sort().join() !== deck.join()) throw new Error(`test fruit deal: ${layout.join(",")} is not a deal of ${deck.join(",")}`);
51	  return { ...dealt, pedestals: dealt.pedestals.map((pedestal, index) => ({ ...pedestal, kit: layout[index]! })) };
52	}
53	
54	/** The pedestal at a dock, if one stands there. */
55	export function pedestalAtDock(sites: readonly PedestalSite[], dock: number): PedestalSite | undefined {
56	  return sites.find((site) => site.dock === dock);
57	}
58	
59	/**
60	 * What an inspection of a pedestal sends its inspector (§9, §16): the fruit's kit with its description, or that the
61	 * pedestal is empty. Only ever sent to a player moored at that pedestal's dock.
62	 */
63	export function inspectionOf(fruits: FruitState, site: PedestalSite): FruitInspectedMessage {
64	  // Every site is one of the state's pedestals.
65	  const inspected = inspectPedestal(fruits, site.id)!;
66	  if (!inspected.full) return { island: site.island, full: false };
67	  const { name, specials, advantage, vulnerability } = inspected.description;
68	  return { island: site.island, full: true, kit: inspected.kit, name, specials: [specials[0], specials[1]], advantage, vulnerability };
69	}

