            for test in spec["tests"]:
                if any(result["status"] not in ("passed", "skipped") for result in test["results"]):
                    names.append(f"`tests/e2e/{spec['file']}` › {spec['title']}")
        for child in suite.get("suites", []):
            walk(child)
    for suite in data.get("suites", []):
        walk(suite)
    if data.get("errors"):
        names.append("(the run failed: " + str(data["errors"][0].get("message", ""))[:160] + ")")
    return names, None

def run_one(scratch, mutation, log):
    mid, area, rel, fn, branch, find, replace, suites = mutation
    path = os.path.join(scratch, rel)
    original = open(os.path.join(WT, rel)).read()
    assert original.count(find) == 1, mid
    open(path, "w").write(original.replace(find, replace))
    failed = []
    notes = []
    try:
        vitest = [s for s in suites.split() if not s.startswith("e2e:")]
        if vitest:
            out = os.path.join(BASE, "out", f"{mid}.vitest.json")
            filters = [f for s in vitest for f in FILTERS[s]]
            projects = []
            if any(s in ("su", "wu") for s in vitest): projects += ["--project", "unit"]
            if any(s not in ("su", "wu") for s in vitest): projects += ["--project", "integration"]
            cmd = ["npx", "vitest", "run", *projects, *filters, "--reporter=json", f"--outputFile={out}"]
            proc = subprocess.run(cmd, cwd=scratch, capture_output=True, text=True, timeout=400)
            names, error = failing_vitest(scratch, out)
            if error: notes.append(error + " " + proc.stderr[-300:])
            failed += names or []
        for spec in [s[4:] for s in suites.split() if s.startswith("e2e:")]:
            out = os.path.join(BASE, "out", f"{mid}.pw.json")
            env = dict(os.environ, PLAYWRIGHT_JSON_OUTPUT_FILE=out)
            proc = subprocess.run(["npx", "--no-install", "playwright", "test", "--config=tests/e2e/playwright.config.ts", "--reporter=json", f"tests/e2e/{spec}"],
                                  cwd=scratch, capture_output=True, text=True, timeout=900, env=env)
            names, error = failing_playwright(scratch, out)
            if error: notes.append(error + " " + proc.stderr[-300:])
            failed += names or []
    finally:
        open(path, "w").write(original)
    record = {"id": mid, "area": area, "file": rel, "function": fn, "branch": branch, "suites": suites, "failed": failed, "notes": notes}
    with open(log, "a") as handle:
        handle.write(json.dumps(record) + "\n")
    print(mid, len(failed), "failing", flush=True)

if __name__ == "__main__":
    worker, count, kind = int(sys.argv[1]), int(sys.argv[2]), sys.argv[3]
    os.makedirs(os.path.join(BASE, "out"), exist_ok=True)
    scratch = os.path.join(BASE, f"s{worker}")
    make_scratch(scratch)
    only = set(sys.argv[4:])
    queue = [m for m in M if (("e2e:" in m[7]) == (kind == "browser")) and (not only or m[0] in only)]
    mine = queue[worker::count] if kind != "browser" else queue
    log = os.path.join(BASE, f"results-{kind}.jsonl")
    for mutation in mine:
        run_one(scratch, mutation, log)
